// src/tools/auth.ts
function registerAuthTools(server2, resourceUri) {
  j(
    server2,
    "garmin-check-auth",
    {
      title: "Check Garmin Auth",
      description: "Check if the user is authenticated with Garmin Connect",
      _meta: { ui: { resourceUri } }
    },
    async () => {
      const client2 = getClient();
      try {
        await client2.resume();
        return {
          content: [{ type: "text", text: JSON.stringify({ authenticated: true }) }]
        };
      } catch {
        return {
          content: [{ type: "text", text: JSON.stringify({ authenticated: false }) }]
        };
      }
    }
  );
  j(
    server2,
    "garmin-get-login-key",
    {
      title: "Get Garmin Login Key",
      description: "Issue a single-use public key for encrypting the Garmin password",
      _meta: { ui: { resourceUri, visibility: ["app"] } }
    },
    async () => ({
      content: [{ type: "text", text: JSON.stringify({ publicKey: issueLoginKey() }) }]
    })
  );
  j(
    server2,
    "garmin-login",
    {
      title: "Garmin Login",
      description: "Log in to Garmin Connect with email and an encrypted password",
      inputSchema: external_exports.object({
        email: external_exports.string(),
        encryptedPassword: external_exports.string().describe("Password encrypted with the key from garmin-get-login-key")
      }),
      _meta: { ui: { resourceUri, visibility: ["app"] } }
    },
    async ({ email: email3, encryptedPassword }) => {
      const client2 = getClient();
      const result = await client2.login(email3, decryptWithLoginKey(encryptedPassword));
      if (result.status === "needs_mfa") {
        return {
          content: [{ type: "text", text: JSON.stringify({ status: "needs_mfa" }) }]
        };
      }
      notifyAuth();
      return {
        content: [{ type: "text", text: JSON.stringify({ status: "success" }) }]
      };
    }
  );
  j(
    server2,
    "garmin-submit-mfa",
    {
      title: "Submit Garmin MFA",
      description: "Submit MFA verification code for Garmin Connect login",
      inputSchema: external_exports.object({ code: external_exports.string() }),
      _meta: { ui: { resourceUri, visibility: ["app"] } }
    },
    async ({ code }) => {
      const client2 = getClient();
      await client2.submitMfa(code);
      notifyAuth();
      return {
        content: [{ type: "text", text: JSON.stringify({ status: "success" }) }]
      };
    }
  );
  j(
    server2,
    "garmin-logout",
    {
      title: "Garmin Logout",
      description: "Log out of Garmin Connect and clear saved tokens",
      _meta: { ui: { resourceUri } }
    },
    async () => {
      const client2 = getClient();
      await client2.logout();
      return {
        content: [{ type: "text", text: JSON.stringify({ status: "logged_out" }) }]
      };
    }
  );
}

